/**
 * The two halves of an OBSERVED compatibility check (D31): what the kit provides, and what a
 * plugin uses.
 *
 * The machinery this replaces asked a plugin to PREDICT its compatibility — `requires.kit` as a
 * semver range, `requires.pluginApi` as an integer — and a prediction goes stale the moment either
 * side moves without the other noticing. Both numbers are written by a person, checked by a
 * matcher, and wrong silently. What is measurable instead:
 *
 *   1. the kit EMITS a ledger of what it provides (`docs/plugin-api.md`, `## Surface ledger`,
 *      generated by `scripts/plugin-api-doc.mjs`);
 *   2. a plugin's USE is a derived fact — the symbols its own files import from a declared entry;
 *   3. compatibility is `uses \ ledger`, a set difference over strings.
 *
 * A set difference is the whole point. It is deterministic, it has no grammar to get wrong, and
 * **it cannot throw** — where a malformed semver range throws out of the matcher and arrives at the
 * caller as a generic failure with nothing to act on, which is the exact shape of bug that made
 * every pin a guess. Whatever is missing names itself, and carries the replacement import when one
 * is knowable.
 *
 * Pure apart from reading files, and nothing runs at import time, so
 * `apps/web/tests/config/surface.test.ts` drives every function with fixtures as well as over the
 * real repository. `surface.d.mts` beside this file is the hand-written type surface (no `allowJs`).
 *
 * **The one non-`node:` dependency, and why it is lazy.** Reading which symbols a file imports is a
 * parse, not a regex: `import { a as b, type c }` and `export { d } from` are four shapes with one
 * meaning, and a regex over them is the kind of check that silently stops matching. So `usesOf`
 * uses the TypeScript compiler's own parser — loaded through `createRequire` at the point of use
 * rather than at the top of the module, so `readLedger` and `missingFrom` still work in a checkout
 * with no `node_modules`. Only the half that needs a parser needs one installed.
 */

import fs from 'node:fs'
import { createRequire } from 'node:module'
import path from 'node:path'

const require = createRequire(import.meta.url)

/** @type {import('typescript') | null} */
let cachedTs = null

/** The TypeScript parser, loaded on first use. See the module header for why this is not a top import. */
function typescript() {
  if (!cachedTs) cachedTs = require('typescript')
  return cachedTs
}

// ---------------------------------------------------------------- the declared entries

/**
 * The ledger's entries, in reading order: the server surface first, then the halves a plugin
 * reaches for less often.
 *
 * `import` is the specifier a plugin actually writes and is the ledger's KEY, so it is the thing
 * both the generator and this module have to agree on — which is why the list lives here and
 * `scripts/plugin-api-doc.mjs` reads it rather than keeping a second copy. The repo path beside it
 * is how an import is resolved back to an entry; a reader never sees it.
 *
 * The CLI entries are spelled as prose because a plugin's CLI half lives beside them and there is
 * no alias for that package — the label is what appears in the ledger, so it has to be stable
 * whatever it looks like.
 */
export const LEDGER_ENTRIES = [
  { import: '@/plugins/api', file: 'apps/web/src/plugins/api/index.ts' },
  { import: '@/plugins/api/peers', file: 'apps/web/src/plugins/api/peers.ts' },
  { import: '@/plugins/api/ui-wiring', file: 'apps/web/src/plugins/api/ui-wiring.ts' },
  { import: '@/plugins/api/ui', file: 'apps/web/src/plugins/api/ui.ts' },
  { import: '@/plugins/types', file: 'apps/web/src/plugins/types.ts' },
  { import: '@/db/schema/kit', file: 'apps/web/src/db/schema/kit.ts' },
  { import: '@rocketflare/shared/plugins/api', file: 'packages/shared/src/plugins/api.ts' },
  { import: "'../api' (apps/cli/src/plugins/api.ts)", file: 'apps/cli/src/plugins/api.ts' },
  { import: "'./types' (apps/cli/src/plugins/types.ts)", file: 'apps/cli/src/plugins/types.ts' },
  { import: '@testkit/integration', file: 'apps/web/tests/kit/integration.ts' },
  { import: '@testkit/unit', file: 'apps/web/tests/kit/unit.ts' },
]

/** Where a plugin's three trees live, by package. */
export const PLUGIN_ROOTS = [
  'apps/web/src/plugins/',
  'packages/shared/src/plugins/',
  'apps/cli/src/plugins/',
]

/**
 * Where a plugin may import the host from. Resolved repo paths, so `@/x`, `../../x` and
 * `@rocketflare/shared/x` all land in the same vocabulary.
 *
 * Wider than `LEDGER_ENTRIES` on purpose: the whole of `packages/shared/src` is importable by a
 * plugin's contract module, while only two of its files are LEDGERED. That gap is the honest
 * boundary of this method rather than a hole in it — see `usesOf`.
 */
export const DECLARED_ENTRIES = [
  // The server surface and the context family, plus the two UI halves and the peer escape hatches.
  'apps/web/src/plugins/api',
  // `ServerPlugin` / `UiPlugin` themselves.
  'apps/web/src/plugins/types',
  // The build-time schema symbols, which cannot be injected: a `pgTable(...)` runs at module scope.
  'apps/web/src/db/schema/kit',
  // The CLI half.
  'apps/cli/src/plugins/api',
  'apps/cli/src/plugins/types',
  // The TEST kit: `@testkit/integration` is the harness (a real database, the real app, the real
  // provider tree), `@testkit/unit` the context builders. A plugin's tests were out of scope for
  // this rule only because there was nowhere to point them; there is now.
  'apps/web/tests/kit',
  // Every shared contract module — the package is the contract, and a plugin's own schemas are
  // built out of it.
  'packages/shared/src',
]

/**
 * Names a plugin may not take as its id.
 *
 * Most are barrel FILENAMES: `plugins/ui.ts` and `plugins/ui/index.ts` would otherwise be two
 * different things spelled the same way in an import. `api` is the plugin API directory
 * (`plugins/api/**`), which is a host surface rather than a plugin and must classify as one —
 * without this, every core import of `@/plugins/api` would read as reaching into a plugin called
 * "api", and the directory would be reported as an installed plugin with no declared surface.
 */
export const RESERVED_PLUGIN_IDS = new Set([
  'index',
  'server',
  'ui',
  'schema',
  'types',
  'api',
  'worker-exports',
])

// ---------------------------------------------------------------- paths and specifiers

/** Drop the extension and a trailing `/index`, so the four entry spellings normalise to one. */
export function normaliseModulePath(p) {
  return p.replace(/\.(tsx?|jsx?)$/, '').replace(/\/index$/, '')
}

/** The plugin id a repo-relative path belongs to, or null when it is not inside a plugin. */
export function pluginIdOfPath(repoPath) {
  for (const root of PLUGIN_ROOTS) {
    if (!repoPath.startsWith(root)) continue
    const rest = repoPath.slice(root.length)
    const id = (rest.split('/')[0] ?? '').replace(/\.(tsx?|jsx?)$/, '')
    // The barrel files themselves belong to no plugin — and a specifier may arrive without an
    // extension (`./plugins/index`), so the name has to be checked, not just the dot.
    if (id === '' || id.includes('.') || RESERVED_PLUGIN_IDS.has(id)) return null
    return id
  }
  return null
}

/**
 * `@/x` → `apps/web/src/x`; `@rocketflare/shared/x` → `packages/shared/src/x`;
 * `@testkit/x` → `apps/web/tests/kit/x`; else relative. A bare third-party specifier is null.
 *
 * `@testkit` is resolved rather than left as an unknown bare specifier, which would be allowed by
 * accident. Mapping it makes it a DECLARED entry like the others.
 */
export function resolveSpecifier(importer, specifier) {
  if (specifier === '@testkit') return 'apps/web/tests/kit'
  if (specifier.startsWith('@testkit/'))
    return `apps/web/tests/kit/${specifier.slice('@testkit/'.length)}`
  if (specifier.startsWith('@/')) return `apps/web/src/${specifier.slice(2)}`
  if (specifier.startsWith('@rocketflare/shared/'))
    return `packages/shared/src/${specifier.slice('@rocketflare/shared/'.length)}`
  if (specifier.startsWith('.'))
    return path.posix.normalize(path.posix.join(path.posix.dirname(importer), specifier))
  return null
}

/**
 * The ledger entry a resolved module path IS, or null.
 *
 * An exact match on the normalised path, never a prefix: `@/plugins/api/peers` is its own entry
 * beside `@/plugins/api`, and a prefix rule would fold the two together and report every peer
 * symbol as missing from the barrel.
 */
export function ledgerEntryOfModule(modulePath) {
  if (!modulePath) return null
  const normalised = normaliseModulePath(modulePath)
  for (const entry of LEDGER_ENTRIES) {
    if (normaliseModulePath(entry.file) === normalised) return entry.import
  }
  return null
}

/**
 * The edit, per kit module a plugin used to reach for.
 *
 * **Every diagnostic carries its replacement**, because installs are performed by agents and a
 * message that says only what is wrong gives one nothing to do. Longest prefix wins, so a whole
 * directory can be answered once and a particular module inside it more precisely.
 */
