/** The replacement import for a resolved kit module, longest prefix first, else the catch-all. */
export function suggestionFor(target) {
  let best
  for (const entry of SUGGESTED_ENTRY) {
    if (target === entry[0] || target.startsWith(`${entry[0]}/`)) {
      if (!best || entry[0].length > best[0].length) best = entry
    }
  }
  return best ? best[1] : "reach the host through '@/plugins/api' (or '@/plugins/api/ui' in a page)"
}

// ---------------------------------------------------------------- reading imports

/**
 * Every static import and re-export of a TypeScript source, with the NAMES it binds.
 *
 * One parse rather than a regex, because the shapes that mean "this file uses that symbol" are
 * `import { a }`, `import { a as b }`, `import { type a }`, `import type { a }` and
 * `export { a } from` — and a regex over those is a check that stops matching without saying so.
 *
 * `propertyName ?? name` is the EXPORTED name: `import { a as b }` uses `a`, which is what the
 * ledger records. **Type-only imports count**, declaration-level and specifier-level alike:
 * removing a type from the surface breaks a plugin exactly as a value does, it just breaks at
 * compile time.
 *
 * A namespace import (`import * as x`) binds no names this can attribute, so it records none and
 * says so with `namespace: true` — a limit of the method, not a claim that nothing is used.
 */
export function moduleImports(source, fileName = 'x.ts') {
  const ts = typescript()
  const file = ts.createSourceFile(fileName, source, ts.ScriptTarget.Latest, true)
  const out = []
  const visit = node => {
    if (
      (ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) &&
      node.moduleSpecifier &&
      ts.isStringLiteral(node.moduleSpecifier)
    ) {
      const isImport = ts.isImportDeclaration(node)
      const clause = isImport ? node.importClause : null
      const typeOnly = isImport ? Boolean(clause?.isTypeOnly) : node.isTypeOnly
      const bindings = isImport ? clause?.namedBindings : node.exportClause
      const names = []
      let namespace = false
      if (bindings && ts.isNamespaceImport(bindings)) namespace = true
      else if (bindings && (ts.isNamedImports(bindings) || ts.isNamedExports(bindings))) {
        for (const element of bindings.elements) {
          names.push((element.propertyName ?? element.name).text)
        }
      }
      const { line } = file.getLineAndCharacterOfPosition(node.getStart(file))
      out.push({ specifier: node.moduleSpecifier.text, names, namespace, typeOnly, line: line + 1 })
    }
    ts.forEachChild(node, visit)
  }
  visit(file)
  return out
}

/** Static import/export specifiers of a TypeScript source, with whether the import is type-only. */
export function staticImports(source) {
  return moduleImports(source).map(({ specifier, typeOnly, line }) => ({
    specifier,
    typeOnly,
    line,
  }))
}

// ---------------------------------------------------------------- the ledger

const LEDGER_HEADING = '## Surface ledger'
const LEDGER_FENCE = '```text'

/**
 * The kit's ledger, from `docs/plugin-api.md`, or **null when there is nothing to read**.
 *
 * Null rather than a throw for three separate absences — no file, no `## Surface ledger` section,
 * no fenced block under it — because every one of them is a legitimate state of somebody's
 * checkout: a copy of the kit made before the ledger existed, a doc deleted by an adopter, a
 * generator that has not run yet. **A caller must treat null as its own failure and say so**; what
 * it must not do is present "no ledger" as "nothing is missing", which is exactly what an empty
 * ledger would silently produce.
 *
 * Two row shapes, because the generator emits both:
 *
 *     <entry> :: <kind> :: <name> :: <signature>
 *     <entry> :: member :: <Type>.<member> :: <signature>
 *
 * They parse identically — the second is only a `kind` of `member` and a dotted `name` — which is
 * what lets `usesOf` and this agree on one key, `"<entry> :: <name>"`. A signature may itself
 * contain ` :: ` (a nested type literal can), so everything past the third separator is rejoined
 * rather than the line being split into exactly four.
 */
export function readLedger(repoRoot) {
  const file = path.join(repoRoot, 'docs/plugin-api.md')
  if (!fs.existsSync(file)) return null
  const markdown = fs.readFileSync(file, 'utf8')
  const start = markdown.indexOf(LEDGER_HEADING)
  if (start === -1) return null
  const fence = markdown.indexOf(LEDGER_FENCE, start)
  if (fence === -1) return null
  const body = markdown.slice(fence + LEDGER_FENCE.length)
  const end = body.indexOf('```')
  const members = new Map()
  for (const raw of body.slice(0, end === -1 ? undefined : end).split('\n')) {
    const parts = raw.trim().split(' :: ')
    if (parts.length < 4) continue
    const [entry, kind, name] = parts
    members.set(`${entry} :: ${name}`, {
      entry,
      kind,
      name,
      signature: parts.slice(3).join(' :: '),
    })
  }
  return {
    members,
    size: members.size,
    has: (entry, name) => members.has(`${entry} :: ${name}`),
    get: (entry, name) => members.get(`${entry} :: ${name}`),
  }
}

// ---------------------------------------------------------------- what a plugin uses

const SOURCE_FILE = /\.(tsx?|jsx?)$/

/** Every source file under `dir`, repo-relative, sorted — so the walk is deterministic. */
function sourceFilesUnder(repoRoot, dir) {
  const abs = path.join(repoRoot, dir)
  if (!fs.existsSync(abs)) return []
  const out = []
  const walk = current => {
    for (const entry of fs.readdirSync(path.join(repoRoot, current), { withFileTypes: true })) {
      const rel = `${current}/${entry.name}`
      if (entry.isDirectory()) {
        if (entry.name === 'node_modules' || entry.name === 'dist') continue
        walk(rel)
      } else if (SOURCE_FILE.test(entry.name)) out.push(rel)
    }
  }
  walk(dir.replace(/\/$/, ''))
  return out.sort()
}

/** The DECLARED entry a resolved module falls under, or null. Exact, or a directory prefix. */
export function declaredEntryOf(modulePath) {
  if (!modulePath) return null
  const normalised = normaliseModulePath(modulePath)
  for (const entry of DECLARED_ENTRIES) {
    if (normalised === entry || normalised.startsWith(`${entry}/`)) return entry
  }
  return null
}

/**
 * A repo path back to the specifier a plugin writes for it — the inverse of `resolveSpecifier`.
 *
 * Needed because `uses` is keyed by the spelling an author would recognise, and a module may be
 * reached by several (`@/db/schema/kit` and `../../../../db/schema/kit` are one key). A ledgered
 * module answers through `LEDGER_ENTRIES`, whose label is the key; this covers the rest.
 */
export function canonicalSpecifier(modulePath) {
  const ledgered = ledgerEntryOfModule(modulePath)
  if (ledgered) return ledgered
  const p = normaliseModulePath(modulePath ?? '')
  if (p === 'apps/web/tests/kit') return '@testkit'
  if (p.startsWith('apps/web/tests/kit/'))
    return `@testkit/${p.slice('apps/web/tests/kit/'.length)}`
  if (p.startsWith('apps/web/src/')) return `@/${p.slice('apps/web/src/'.length)}`
  if (p.startsWith('packages/shared/src/'))
    return `@rocketflare/shared/${p.slice('packages/shared/src/'.length)}`
  return p === '' ? null : p
}

/**
 * What a plugin USES of the host surface: `{ [entry]: [sorted unique symbol names] }`.
 *
 * Derived, never declared. That is the whole reason this replaces a version a person types: a
 * number is a claim, and this is a measurement of the same files the compiler reads. It walks the
 * plugin's three trees AND its own tests — the tests were out of the import rule once only because
 * there was nowhere to point them, and in practice they held the worst of the coupling.
 *
 * **It records every import of a DECLARED entry, ledgered or not, and the difference from what it
 * used to do is the whole point.** Keyed by ledger entry alone, a plugin importing
 * `@rocketflare/shared/pagination` measured as using *nothing*: the whole of `packages/shared/src`
 * is a declared entry while only one of its files is ledgered, so the import was dropped in the
 * WALK and no later reader could tell it apart from a plugin that imports nothing at all. Silently
 * losing the measurement is exactly what this machinery exists to stop, so the data is kept here
 * and the POLICY — which entries the ledger is entitled to judge — lives in `missingFrom`.
 *
 * Still ignored, because there is no host surface on the other side: imports that resolve inside
 * the plugin itself, into another plugin, or to a third-party package. Whether reaching somewhere
 * UNdeclared was allowed at all is `tests/helpers/plugins.ts`'s rule, not this measurement's.
 */
export function usesOf(repoRoot, pluginId) {
  const byEntry = new Map()
  for (const root of PLUGIN_ROOTS) {
    for (const file of sourceFilesUnder(repoRoot, `${root}${pluginId}`)) {
      const source = fs.readFileSync(path.join(repoRoot, file), 'utf8')
      for (const imported of moduleImports(source, file)) {
        const target = resolveSpecifier(file, imported.specifier)
        // Inside this plugin, or inside another one: neither is host surface.
        if (!target || pluginIdOfPath(target) !== null) continue
        if (!declaredEntryOf(target)) continue
        const entry = canonicalSpecifier(target)
        if (!entry) continue
        if (!byEntry.has(entry)) byEntry.set(entry, new Set())
        for (const name of imported.names) byEntry.get(entry).add(name)
      }
    }
  }
  // Ledger order first, then everything else alphabetically, so two runs and two readers see the
  // same document.
  const uses = {}
  const ledgerOrder = LEDGER_ENTRIES.map(e => e.import)
  const rest = [...byEntry.keys()].filter(k => !ledgerOrder.includes(k)).sort()
  for (const entry of [...ledgerOrder, ...rest]) {
    const names = byEntry.get(entry)
    if (names && names.size > 0) uses[entry] = [...names].sort((a, b) => a.localeCompare(b, 'en'))
  }
  return uses
}

/**
 * `uses \ ledger` — every symbol a plugin names that the kit no longer provides.
 *
 * The primitive the whole redesign rests on: a set difference over strings. No range to parse, no
 * comparison that can be malformed, and **no path out of here that throws**. An empty result is a
 * plugin that fits; a non-empty one names each symbol and, where it is knowable, the exact import
 * that replaces it.
 *
 * `suggestion` is the honest half. When the symbol still exists under a DIFFERENT entry it has
 * moved, and the replacement import is a fact this can compute — which is the common case, because
 * a surface is far more often reorganised than deleted. When it exists nowhere the suggestion is
 * `null`: inventing one would send the reader to a name that is not there, which is worse than
 * saying nothing (the same reason the capability index is checked rather than hand-maintained).
 *
 * **A null ledger yields an empty list, and the caller owns that.** This function cannot
 * distinguish "nothing is missing" from "there was nothing to compare against", so a caller that
 * treats null as a pass has disabled its own check — `readLedger` says why it may be null.
 */
export function missingFrom(uses, ledger) {
  if (!ledger) return []
  const elsewhere = new Map()
  // Which entries this ledger is entitled to judge. Derived from the ledger itself rather than
  // from a second list, so an entry that stops being emitted stops being judged in the same
  // breath. This is the policy `usesOf` deliberately does NOT apply: the whole of
  // `packages/shared/src` is importable while only part of it is ledgered, and a key with no
  // ledger side would report every symbol under it as missing — a flood that says nothing.
  const covered = new Set()
  for (const member of ledger.members.values()) {
    covered.add(member.entry)
    if (!elsewhere.has(member.name)) elsewhere.set(member.name, member.entry)
  }
  const missing = []
  for (const [entry, names] of Object.entries(uses ?? {})) {
    if (!covered.has(entry)) continue
    for (const symbol of names) {
      if (ledger.has(entry, symbol)) continue
      const moved = elsewhere.get(symbol)
      missing.push({
        entry,
        symbol,
        suggestion: moved ? `import { ${symbol} } from '${moved}'` : null,
      })
    }
  }
  return missing
}
